      SUBROUTINE RDTEST(STRING,FLAG)C---- NEXT INPUT CHARACTER MUST BE CONTAINED IN "STRING"C-------------------------------------------------------------------      CHARACTER *(*)  STRING      LOGICAL         FLAGC-------------------------------------------------------------------      INCLUDE 'IOUNIT.CIN'      INCLUDE 'RDBUFF.CIN'C-------------------------------------------------------------------      FLAG = .FALSE.      IF (INDEX(STRING,ITEM) .EQ. 0) THEN        CALL RDFAIL        IF (LEN(STRING) .EQ. 1) THEN          WRITE (NOUT,910) STRING        ELSE          WRITE (NOUT,920) STRING        ENDIF        FLAG = .TRUE.      ENDIF      RETURNC-------------------------------------------------------------------  910 FORMAT(' *** ERROR *** "',A1,'" EXPECTED'/' ')  920 FORMAT(' *** ERROR *** ONE OF "',A,'" EXPECTED'/' ')C-------------------------------------------------------------------      END